<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\{Database,Finance,FinanceReports};
if(PHP_SAPI!=='cli')exit(1);
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);
$db->exec("INSERT INTO clubs VALUES('a','Synthetischer Testverein'),('b','Fremd'); INSERT INTO actors(id,club_id,role) VALUES('a','a','treasurer'),('b','b','treasurer'),('editor','a','editor')");
$f=new Finance($db,'a');$key=fn()=>bin2hex(random_bytes(16));$n=0;
$check=static function(bool $ok,string $label)use(&$n){if(!$ok)throw new RuntimeException($label);++$n;echo "PASS $label\n";};
$deny=static function(callable $call,string $label)use($check){try{$call();}catch(DomainException){$check(true,$label);return;}throw new RuntimeException($label);};
$atomic=static function(callable $fn)use($db){$db->exec('START TRANSACTION');try{$r=$fn();$db->exec('COMMIT');return $r;}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}};
$bank=$f->createAccount('Bank','offline','0','2025-01-01');$other=$f->createAccount('Andere Bank','offline','0','2025-01-01');
$entry=$f->createEntry(['kind'=>'contribution','category'=>'membership','description'=>'Synthetischer Beitrag','counterparty'=>'Testperson','document_date'=>'2025-01-01','due_date'=>'2025-01-01','positions'=>[
 ['description'=>'Teil A','amount'=>'10.01','sphere'=>'1','account'=>'','tax_rate'=>'0'],
 ['description'=>'Teil B','amount'=>'5.98','sphere'=>'1','account'=>'','tax_rate'=>'0'],
]],$key());
$move=fn($day,$direction,$amount='15.99',$account=null)=>$f->createTransaction(['account'=>$account??$bank,'booked_on'=>$day,'direction'=>$direction,'amount'=>$amount,'description'=>'Synthetischer Kontoauszug','counterparty'=>'Testperson'],$key());
$pay=function($tx,$amount)use($f,$entry,$key){return $f->allocate($tx,(int)$f->transactionDetail($tx)['version'],$entry,(int)$f->entry($entry)['version'],$amount,$key());};
$positive=$move('2025-02-01','income');$pay($positive,'15.99');$negative=$move('2025-03-01','expense');
$deny(fn()=>$f->reconcileReturnedDebitLocked($entry,$positive,$negative,'Test'), 'requires atomic caller');
$deny(fn()=>$atomic(fn()=>(new Finance($db,'editor'))->reconcileReturnedDebitLocked($entry,$positive,$negative,'Test')), 'editor cannot change matching');
$deny(fn()=>$atomic(fn()=>(new Finance($db,'b'))->reconcileReturnedDebitLocked($entry,$positive,$negative,'Test')), 'foreign actor cannot inspect payment');
$wrong=$move('2025-03-01','expense','16.99');$deny(fn()=>$atomic(fn()=>$f->reconcileReturnedDebitLocked($entry,$positive,$wrong,'Gebühren')), 'fee-inclusive total rejected');
$wrongAccount=$move('2025-03-01','expense','15.99',$other);$deny(fn()=>$atomic(fn()=>$f->reconcileReturnedDebitLocked($entry,$positive,$wrongAccount,'Test')), 'other account rejected');
$early=$move('2025-01-01','expense');$deny(fn()=>$atomic(fn()=>$f->reconcileReturnedDebitLocked($entry,$positive,$early,'Test')), 'return preceding original rejected');
$count=count($f->transactions());
$atomic(fn()=>$f->reconcileReturnedDebitLocked($entry,$positive,$negative,'Rücklastschrift laut Auszug'));
$check(count($f->transactions())===$count,'does not create any payment');
$check($f->entry($entry)['payment_state']==='open'&&$f->entry($entry)['remaining_cents']===1599,'demand reopened in full');
$check(!$db->query('SELECT 1 FROM finance_reversals')->fetch(),'original invoice not cancelled');
$check($f->transactionDetail($negative)['reversal_of']===$positive,'existing bank return linked');
$deny(fn()=>$atomic(fn()=>$f->reconcileReturnedDebitLocked($entry,$positive,$negative,'Nochmals')), 'return cannot be counted twice');
$report=new FinanceReports($db,'a');$filters=['from'=>'2025-02-01','to'=>'2025-03-31','account'=>$bank];
$rows=$report->journal($filters)['rows'];$selected=array_values(array_filter($rows,fn($r)=>in_array($r['transaction_id'],[$positive,$negative],true)));
$check(count($selected)===4&&array_sum(array_column($selected,'signed_cents'))===0,'original and return offset by exact position cents');
$repay=$move('2025-04-01','income');$pay($repay,'15.99');
$check($f->entry($entry)['payment_state']==='paid'&&$f->entry($entry)['paid_on']==='2025-04-01','new actual payment closes same demand');
$all=$report->journal(['from'=>'2025-02-01','to'=>'2025-04-30','account'=>$bank]);
$again=array_values(array_filter($all['rows'],fn($r)=>$r['transaction_id']===$repay));
$check(array_column($again,'amount_cents')===[1001,598],'repeat collection preserves original position allocation');
$period=$report->journal(['from'=>'2025-04-01','to'=>'2025-04-30','account'=>$bank]);
$check($again===$period['rows'],'filtered report agrees with complete history after return');
$return2=$move('2025-05-01','expense');$atomic(fn()=>$f->reconcileReturnedDebitLocked($entry,$repay,$return2,'Weitere echte Rücklastschrift'));
$check($f->entry($entry)['payment_state']==='open','second actual return also reopens demand');
$partial=$move('2025-06-01','income','7.00');$pay($partial,'7.00');
$check($f->entry($entry)['remaining_cents']===899,'later partial payment has exact remaining amount');
$j=$report->journal(['from'=>'2025-01-01','to'=>'2025-06-30','account'=>$bank]);
$check(array_sum(array_column(array_filter($j['rows'],fn($r)=>$r['entry_id']===$entry),'signed_cents'))===700,'journal retains only actual unreversed contribution income');
$check(\Kulturhus\Verein\Tests\MySqlFixture::integrity($db)==='ok'&&!(\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db)[0]??false),'foreign keys and stored history intact');
echo "$n returned debit checks passed; synthetic only, no network or mail\n";
